<template>
<div class="app-container p-4">
<header class="heading"><div><h2>模型与授权</h2><p>登记模型、验证真实连接，并决定哪些员工可以使用。</p></div><el-button type="primary" @click="edit()">新增模型</el-button></header>
<el-alert v-if="error" :title="error" type="error" :closable="false" />
<el-skeleton v-if="loading" :rows="6" animated />
<el-table v-else :data="rows" empty-text="尚未登记模型"><el-table-column prop="name" label="显示名称" min-width="140" /><el-table-column prop="provider_name" label="Provider" min-width="130" /><el-table-column prop="code" label="实际 Model ID" min-width="220" /><el-table-column label="验证状态" width="140"><template #default="{row}"><el-tag :type="row.enabled && row.verified_status==='VERIFIED'?'success':'info'">{{ !row.enabled?'已停用':row.verified_status==='VERIFIED'?'连接已验证':'待验证' }}</el-tag></template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" @click="edit(row as ModelRow)">编辑</el-button><el-button link type="primary" @click="openGrants(row as ModelRow)">授权</el-button><el-button link type="primary" @click="openTests(row as ModelRow)">验证连接</el-button></template></el-table-column></el-table>
<div class="paging"><el-button :disabled="page===1||loading" @click="page--;load()">上一页</el-button><span>第 {{ page }} 页</span><el-button :disabled="rows.length<30||loading" @click="page++;load()">下一页</el-button></div>
<el-dialog v-model="dialog" :title="editing?'编辑模型':'新增模型'" width="640px" destroy-on-close><el-form label-position="top">
<el-form-item label="Provider"><el-select v-model="form.providerId" placeholder="选择 Provider" filterable><el-option v-for="p in providers" :key="p.id" :label="p.name" :value="p.id" /></el-select></el-form-item>
<el-form-item label="实际 Model ID"><el-input v-model="form.code" placeholder="服务商的模型 ID 或推理接入点 ID" /></el-form-item><el-form-item label="显示名称"><el-input v-model="form.name" placeholder="员工看到的模型名称" /></el-form-item>
<div class="grid"><el-form-item label="上下文窗口（Token）"><el-input-number v-model="form.contextWindow" :min="1024" :max="2000000" /></el-form-item><el-form-item label="最大输出 Token"><el-input-number v-model="form.maxOutputTokens" :min="1" :max="32768" /></el-form-item><el-form-item label="流式输出"><el-switch v-model="form.streaming" /></el-form-item><el-form-item label="Tool Calling 能力"><el-switch v-model="form.tools" /></el-form-item><el-form-item label="Temperature（可选）"><el-input v-model="temperature" placeholder="留空使用默认值" /></el-form-item><el-form-item label="Top P（可选）"><el-input v-model="topP" placeholder="0–1；留空使用默认值" /></el-form-item><el-form-item label="计费币种"><el-select v-model="currency"><el-option label="人民币 CNY" value="CNY" /><el-option label="美元 USD" value="USD" /></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled" /></el-form-item><el-form-item label="每百万输入 Token 价格（可选）"><el-input v-model="inputPrice" placeholder="未设置" /></el-form-item><el-form-item label="每百万输出 Token 价格（可选）"><el-input v-model="outputPrice" placeholder="未设置" /></el-form-item></div>
<el-alert title="保存修改会终止该模型的在途任务，并重置验证状态。" type="warning" :closable="false" /><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存模型</el-button></template></el-dialog>
<el-dialog v-model="grantDialog" :title="'模型授权 · '+selected?.name" width="720px"><el-alert title="授权只决定模型使用资格，不授予他人的助手、知识或凭据权限。撤销会取消该模型的在途任务。" type="info" :closable="false" /><el-form label-position="top" class="grant-form"><el-form-item label="授权范围"><el-select v-model="subjectType" @change="subjectId='';lookup='';targets=[]"><el-option label="全体员工" value="ALL" /><el-option label="用户" value="USER" /><el-option label="部门" value="DEPARTMENT" /><el-option label="角色" value="ROLE" /></el-select></el-form-item><el-form-item v-if="subjectType!=='ALL'" label="查找授权对象"><el-input v-model="lookup" placeholder="输入名称后查找" @keyup.enter="searchTargets"><template #append><el-button :loading="searching" @click="searchTargets">查找</el-button></template></el-input><el-select v-model="subjectId" placeholder="选择授权对象"><el-option v-for="t in targets" :key="t.id" :label="t.name" :value="t.id" /></el-select></el-form-item><el-button type="primary" :loading="saving" @click="grant">添加授权</el-button></el-form><el-skeleton v-if="grantLoading" :rows="3" animated /><el-table v-else :data="grants" empty-text="此模型尚未授权"><el-table-column prop="subject_type" label="范围" /><el-table-column prop="subject_id" label="对象 ID" /><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" :disabled="saving" @click="revoke(row as GrantRow)">撤销</el-button></template></el-table-column></el-table></el-dialog>
<el-dialog v-model="testDialog" :title="'连接验证 · '+selected?.name" width="1100px"><p>测试向所选 Provider 和 Model ID 发起短文本请求。连接通过不代表所有工具或视觉能力已验证。</p><el-button type="primary" :loading="testing" @click="runTest">发起真实测试</el-button><el-table :data="tests" empty-text="尚无测试记录"><el-table-column prop="status" label="结果" width="80" /><el-table-column prop="model_code" label="实际 Model ID" min-width="200" /><el-table-column prop="request_id" label="Request ID" min-width="190" /><el-table-column prop="latency_ms" label="耗时 ms" width="100" /><el-table-column prop="error_code" label="错误" min-width="120" /><el-table-column prop="created_at" label="时间" min-width="170" /></el-table></el-dialog>
</div>
</template>
<script setup lang="ts">
import {modelApi,type ModelRow,type ProviderRow,type GrantRow,type TestRow} from '@/features/workspace/models';
import request from '@/utils/request';
const rows=ref<ModelRow[]>([]),providers=ref<ProviderRow[]>([]),loading=ref(true),error=ref(''),page=ref(1),dialog=ref(false),saving=ref(false),saveError=ref(''),editing=ref<string>();
const selected=ref<ModelRow>(),grants=ref<GrantRow[]>([]),tests=ref<TestRow[]>([]),grantDialog=ref(false),testDialog=ref(false),grantLoading=ref(false),testing=ref(false),searching=ref(false);
const subjectType=ref('USER'),subjectId=ref(''),lookup=ref(''),targets=ref<{id:string;name:string}[]>([]);
const temperature=ref(''),topP=ref(''),currency=ref('CNY'),inputPrice=ref(''),outputPrice=ref('');
const defaults=()=>({providerId:'',code:'',name:'',enabled:true,streaming:true,tools:true,vision:false,contextWindow:32000,maxOutputTokens:2048,expectedVersion:undefined as number|undefined});const form=reactive(defaults());
async function load(){loading.value=true;error.value='';try{rows.value=(await modelApi.models(page.value)).data;}catch{error.value='模型加载失败，请重试。';}finally{loading.value=false;}}
async function edit(row?:ModelRow){try{providers.value=(await modelApi.providers()).data;}catch{ElMessage.error('无法加载 Provider');return;}editing.value=row?.id;Object.assign(form,row?{providerId:row.provider_id,code:row.code,name:row.name,enabled:row.enabled,streaming:row.streaming,tools:row.tools,vision:row.vision,contextWindow:row.context_window,maxOutputTokens:row.max_output_tokens,expectedVersion:row.version}:defaults());const parameters=JSON.parse(row?.default_parameters||'{}'),cost=JSON.parse(row?.cost_config||'{}');temperature.value=parameters.temperature===undefined?'':String(parameters.temperature);topP.value=parameters.top_p===undefined?'':String(parameters.top_p);currency.value=cost.currency||'CNY';inputPrice.value=cost.inputPerMillion===undefined?'':String(cost.inputPerMillion);outputPrice.value=cost.outputPerMillion===undefined?'':String(cost.outputPerMillion);saveError.value='';dialog.value=true;}
async function save(){if(!form.providerId||!form.code||!form.name){saveError.value='请选择 Provider，并填写模型 ID 和名称。';return;}const parameters:Record<string,number>={},cost:Record<string,string|number>={currency:currency.value};if(temperature.value)parameters.temperature=Number(temperature.value);if(topP.value)parameters.top_p=Number(topP.value);if(inputPrice.value)cost.inputPerMillion=Number(inputPrice.value);if(outputPrice.value)cost.outputPerMillion=Number(outputPrice.value);if([...Object.values(parameters),...Object.values(cost).filter(x=>typeof x==='number')].some(x=>!Number.isFinite(x))){saveError.value='参数和价格必须填写数字。';return;}saving.value=true;try{await modelApi.saveModel(editing.value,{...form,defaultParameters:parameters,costConfig:cost});dialog.value=false;ElMessage.success('模型已保存');await load();}catch{saveError.value='保存失败，请检查参数或重新加载最新版本。';}finally{saving.value=false;}}
async function openGrants(row:ModelRow){selected.value=row;grantDialog.value=true;grantLoading.value=true;try{grants.value=(await modelApi.grants(row.id)).data;}catch{ElMessage.error('授权加载失败');}finally{grantLoading.value=false;}}
async function searchTargets(){searching.value=true;try{const kind=subjectType.value==='USER'?'user':subjectType.value==='ROLE'?'role':'dept';const key=kind==='user'?'userName':kind==='role'?'roleName':'deptName';const r=await request({url:'/system/'+kind+'/list',params:{pageNum:1,pageSize:30,[key]:lookup.value}});const items=Array.isArray(r.data)?r.data:r.data.rows;targets.value=items.map((x:Record<string,unknown>)=>({id:String(x[kind+'Id']),name:String(x[kind==='user'?'userName':kind+'Name'])}));}catch{ElMessage.error('查询失败，请确认具有查看用户、部门或角色的权限。');}finally{searching.value=false;}}
async function grant(){if(!selected.value||(!subjectId.value&&subjectType.value!=='ALL'))return;saving.value=true;try{await modelApi.grant(selected.value.id,{subjectType:subjectType.value,subjectId:subjectType.value==='ALL'?'0':subjectId.value});await openGrants(selected.value);ElMessage.success('授权已添加');}finally{saving.value=false;}}
async function revoke(row:GrantRow){if(!selected.value)return;await ElMessageBox.confirm('撤销授权并取消该模型的在途任务？','撤销模型授权',{type:'warning'});saving.value=true;try{await modelApi.revoke(selected.value.id,row.id);await openGrants(selected.value);}finally{saving.value=false;}}
async function openTests(row:ModelRow){selected.value=row;tests.value=[];testDialog.value=true;tests.value=(await modelApi.tests(row.id)).data;}
async function runTest(){if(!selected.value)return;testing.value=true;try{const result=(await modelApi.test(selected.value.id)).data;tests.value=(await modelApi.tests(selected.value.id)).data;if(result.status==='PASS')ElMessage.success('真实连接测试通过');else ElMessage.error('连接测试失败：'+(result.error_code||'请检查 Provider 配置和 Model ID'));await load();}finally{testing.value=false;}}
onMounted(load);
</script>
<style scoped>.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.heading h2{margin:0 0 8px}.heading p{color:var(--el-text-color-secondary)}.paging{display:flex;align-items:center;justify-content:flex-end;gap:14px;margin-top:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.grant-form{margin:20px 0}.el-select{width:100%}</style>
